// Build the 30-day lookback window in ISO format (UTC).
// The scheduler fires at 14:00 UTC = 09:00 America/New_York (EST).
const now = new Date();
const thirtyDaysAgo = new Date(now);
thirtyDaysAgo.setDate(now.getDate() - 30);

const fmt = (d) => d.toISOString().split('T')[0];

return [{
  json: {
    startDate: fmt(thirtyDaysAgo),
    endDate: fmt(now),
    generatedAt: now.toISOString()
  }
}];

// ─── Hardcoded cost benchmarks (cents) ───────────────────────────────────
// These mirror the seeded defaults in job_cost_benchmarks migration MUR-10.
// emergency_repair : $200.00 → 20000 cents
// standard_repair  : $187.50 → 18750 cents
// installation     : $625.00 → 62500 cents
// maintenance      :  $85.00 →  8500 cents
//
// If you add a new service_type to the DB benchmarks table, add it here too.
const COST_BENCHMARKS = {
  emergency_repair: 20000,
  standard_repair:  18750,
  installation:     62500,
  maintenance:       8500
};

const MARGIN_THRESHOLD = 40; // percent

// ─── Pull raw invoice rows ────────────────────────────────────────────────
const invoices = $input.all().map(i => i.json);

// ─── Aggregate revenue per service_type ──────────────────────────────────
// { service_type: { totalRevenueCents: number, count: number } }
const agg = {};

for (const inv of invoices) {
  const serviceType = inv.job?.service_type;
  // Skip rows where the job relationship is missing or type is unknown
  if (!serviceType) continue;

  if (!agg[serviceType]) {
    agg[serviceType] = { totalRevenueCents: 0, count: 0 };
  }
  agg[serviceType].totalRevenueCents += (inv.total_cents || 0);
  agg[serviceType].count += 1;
}

// ─── Calculate margin per service_type ───────────────────────────────────
const results = [];

for (const [serviceType, data] of Object.entries(agg)) {
  if (data.count === 0) continue;

  const avgRevenueCents = data.totalRevenueCents / data.count;
  const costCents = COST_BENCHMARKS[serviceType];

  // If we have no benchmark for this type, skip it (can't compute margin)
  if (costCents === undefined) continue;

  const marginPct = avgRevenueCents > 0
    ? ((avgRevenueCents - costCents) / avgRevenueCents) * 100
    : 0;

  results.push({
    serviceType,
    avgRevenueCents: Math.round(avgRevenueCents),
    avgRevenueDollars: (avgRevenueCents / 100).toFixed(2),
    costCents,
    costDollars: (costCents / 100).toFixed(2),
    marginPct: parseFloat(marginPct.toFixed(2)),
    belowThreshold: marginPct < MARGIN_THRESHOLD,
    invoiceCount: data.count
  });
}

// Sort: below-threshold types first, then by margin ascending
results.sort((a, b) => {
  if (a.belowThreshold && !b.belowThreshold) return -1;
  if (!a.belowThreshold && b.belowThreshold) return 1;
  return a.marginPct - b.marginPct;
});

const belowThresholdTypes = results.filter(r => r.belowThreshold);
const hasAlert = belowThresholdTypes.length > 0;

const window = $('Calculate 30-Day Window').item.json;

return [{
  json: {
    hasAlert,
    belowThresholdTypes,
    allResults: results,
    totalInvoicesAnalyzed: invoices.length,
    period: `${window.startDate} – ${window.endDate}`,
    generatedAt: window.generatedAt,
    thresholdPct: MARGIN_THRESHOLD
  }
}];

// Build a detailed issue description for the CEO Agent.
// true branch — at least one service type is below the 40% threshold.
const data = $('Calculate Margins by Service Type').item.json;

const fmt$ = (cents) => `$${(cents / 100).toFixed(2)}`;
const fmtPct = (p) => `${p.toFixed(2)}%`;

// ─── Alert summary table ──────────────────────────────────────────────────
const alertRows = data.belowThresholdTypes
  .map(r =>
    `| ${r.serviceType} | ${r.invoiceCount} | ${fmt$(r.avgRevenueCents)} | ${fmt$(r.costCents)} | ${fmtPct(r.marginPct)} | BELOW THRESHOLD |`
  )
  .join('\n');

// ─── All service types for full context ──────────────────────────────────
const allRows = data.allResults
  .map(r =>
    `| ${r.serviceType} | ${r.invoiceCount} | ${fmt$(r.avgRevenueCents)} | ${fmt$(r.costCents)} | ${fmtPct(r.marginPct)} | ${r.belowThreshold ? '⚠ BELOW' : '✓ OK'} |`
  )
  .join('\n');

const alertTypeList = data.belowThresholdTypes
  .map(r => `- **${r.serviceType}**: ${fmtPct(r.marginPct)} margin (avg revenue ${fmt$(r.avgRevenueCents)} vs ${fmt$(r.costCents)} benchmark cost, ${r.invoiceCount} invoice(s))`)
  .join('\n');

const title = `CRITICAL: Job Margin Alert — ${data.belowThresholdTypes.length} service type(s) below ${data.thresholdPct}% threshold`;

const description = `# Job Profitability Margin Alert

**Severity:** CRITICAL  
**Period:** ${data.period}  
**Generated:** ${new Date(data.generatedAt).toLocaleString('en-US', { timeZone: 'America/New_York' })}  
**Threshold:** ${data.thresholdPct}% minimum margin  
**Total invoices analyzed:** ${data.totalInvoicesAnalyzed}

---

## Service Types Below ${data.thresholdPct}% Threshold

${alertTypeList}

---

## Below-Threshold Detail

| Service Type | # Invoices | Avg Revenue | Benchmark Cost | Margin % | Status |
|-------------|------------|-------------|----------------|----------|--------|
${alertRows}

---

## Full Profitability Breakdown (Last 30 Days)

| Service Type | # Invoices | Avg Revenue | Benchmark Cost | Margin % | Status |
|-------------|------------|-------------|----------------|----------|--------|
${allRows}

---

## Recommended Actions

1. Review pricing for flagged service types against current market rates.
2. Audit parts sourcing costs — consider alternate suppliers for high-parts-cost jobs.
3. Review technician time tracking to identify inefficiencies in labor.
4. Check if discounts or write-offs are inflating the cost-to-revenue gap.
5. Update cost benchmarks in Supabase \`job_cost_benchmarks\` table if costs have changed.

---
_Automated alert from Operations Agent — Murray's AI Command Center (MUR-10)_`;

return [{
  json: {
    title,
    description,
    data
  }
}];

