    message: 'All margins healthy — no service type is below the 40% threshold.',
    period: data.period,
    serviceTypes: data.allResults.map(r => ({
      serviceType: r.serviceType,
      marginPct: r.marginPct,
      invoiceCount: r.invoiceCount
    }))
  }
}];
